import {test,expect} from '@playwright/test';
async function quote(page,service){await page.goto('/');await page.getByRole('combobox',{name:'Service',exact:true}).selectOption(service);await page.getByLabel('Town / postcode').fill('Edinburgh EH1');await page.getByRole('button',{name:'See demo guide price'}).click();await expect(page.getByText('ILLUSTRATIVE DEMO RANGE')).toBeVisible();}
test('customer request persists and business status can be updated',async({page},info)=>{const errors=[];page.on('pageerror',e=>errors.push(e.message));await quote(page,'roofing');await page.getByRole('button',{name:'Choose a preferred time'}).click();await page.getByLabel('Preferred date').fill('2027-12-20');await page.getByLabel('Your name').fill('Browser Customer');await page.getByLabel('Email address').fill('customer@example.test');await page.getByLabel('Phone number').fill('07000000000');await page.getByRole('button',{name:'Save appointment request'}).click();await expect(page.getByRole('heading',{name:'This is a request, not a confirmed booking.'})).toBeVisible();await page.getByRole('link',{name:'Business demo'}).click();await page.getByLabel('Search enquiries').fill('Browser Customer');await page.getByText('Browser Customer',{exact:true}).click();await expect(page.getByText('40 m² approximate area')).toBeVisible();await page.getByRole('combobox',{name:'Enquiry status'}).selectOption('Contacted');await expect(page.getByText('Status saved in this browser.')).toBeVisible();await page.reload();await page.getByLabel('Search enquiries').fill('Browser Customer');await expect(page.locator('#results .badge')).toHaveText('Contacted');await page.getByRole('combobox',{name:'Status filter'}).selectOption('Closed');await expect(page.getByText('No enquiries match your filters. Try another search.')).toBeVisible();expect(errors).toEqual([]);await page.screenshot({path:`artifacts/${info.project.name}-dashboard.png`,fullPage:true});});
for(const service of ['roughcasting','openings'])test(`${service} quote path and back navigation`,async({page})=>{await quote(page,service);await page.getByRole('button',{name:'Back'}).click();await expect(page.getByRole('combobox',{name:'Service',exact:true})).toHaveValue(service);await expect(page.getByLabel('Town / postcode')).toHaveValue('Edinburgh EH1');});
test('mobile layout and service input validation',async({page},info)=>{await page.goto('/');await expect(page.getByRole('heading',{name:'What can we help you with?'})).toBeVisible();await page.screenshot({path:`artifacts/${info.project.name}-customer.png`,fullPage:true});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.getByRole('combobox',{name:'Service',exact:true}).selectOption('openings');await page.getByLabel('Number of windows').fill('0');await page.getByLabel('Number of doors').fill('0');await page.getByLabel('Town / postcode').fill('Glasgow');await page.getByRole('button',{name:'See demo guide price'}).click();await expect(page.getByRole('alert')).toContainText('Enter at least one');});
test('invalid contact and past dates cannot submit',async({page})=>{await quote(page,'roofing');await page.getByRole('button',{name:'Choose a preferred time'}).click();await page.getByLabel('Preferred date').fill('2020-01-01');await page.getByRole('button',{name:'Save appointment request'}).click();await expect(page.getByRole('heading',{name:'When would suit you?'})).toBeVisible();});
test('storage write failure keeps request unsaved',async({page})=>{await quote(page,'roofing');await page.getByRole('button',{name:'Choose a preferred time'}).click();await page.getByLabel('Preferred date').fill('2027-12-20');await page.getByLabel('Your name').fill('Test');await page.getByLabel('Email address').fill('test@example.test');await page.getByLabel('Phone number').fill('000');await page.evaluate(()=>{Storage.prototype.setItem=()=>{throw Error('Storage unavailable');};});await page.getByRole('button',{name:'Save appointment request'}).click();await expect(page.getByRole('alert')).toContainText('Storage unavailable');await expect(page.getByRole('heading',{name:'When would suit you?'})).toBeVisible();});
